import { supabaseClient } from './supabase-client.js';
const $ = id => document.getElementById(id);
const esc = (v='') => String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const params = new URLSearchParams(location.search);let edition=String(params.get('edition')||'').toLowerCase();if(!['basic','expert'].includes(edition)){try{edition=String(localStorage.getItem('aclSelectedEdition')||'expert').toLowerCase()}catch{edition='expert'}}if(!['basic','expert'].includes(edition))edition='expert';try{localStorage.setItem('aclSelectedEdition',edition)}catch{}
function addCss(href){if(document.querySelector(`link[href^="${href.split('?')[0]}"]`))return;const l=document.createElement('link');l.rel='stylesheet';l.href=href;document.head.appendChild(l)}
addCss('assets/css/brand-restoration-20260820.css?v=3');addCss('assets/css/module-card-intelligence-20260820.css?v=1');
const headerLogo=document.querySelector('.acl-command-brand-logo');if(headerLogo)headerLogo.src='assets/images/acl-header-mark.svg';
const ESC_GUIDELINE_SLUGS=new Set(['chronic-coronary-syndromes','acute-coronary-syndromes','heart-failure','atrial-fibrillation','valvular-heart-disease','hypertension','non-cardiac-surgery','cvd-pregnancy','infective-endocarditis','myocarditis-pericarditis','dyslipidaemia','peripheral-arterial-aortic-diseases','cardiomyopathies','cvd-diabetes','pulmonary-hypertension','ventricular-arrhythmias-scd','cardiac-pacing','sports-cardiology-exercise']);
const isEscGuideline=m=>edition==='expert'&&ESC_GUIDELINE_SLUGS.has(String(m?.slug||'').trim().toLowerCase());
const escBadge=()=>'<img class="esc-guideline-logo" src="assets/images/esc-guideline-mark.svg" alt="ESC guideline">';
const grid=$('modules'),status=$('modulesStatus'),summary=$('catalogueSummary'),search=$('moduleSearchInputCompact'),availability=$('moduleAvailabilityCompact'),progressFilter=$('moduleProgressCompact'),searchSummary=$('moduleSearchSummary'),clear=$('clearModuleFiltersCompact');let modules=[],attempts=[];
function show(msg='',kind=''){if(!status)return;status.textContent=msg;status.className=`status-box ${kind}`.trim();status.hidden=!msg}
function launch(m){if(!m.launch_path)return'';try{const u=new URL(m.launch_path,location.href);if(edition==='expert'&&(u.pathname.endsWith('/learning.html')||u.pathname.endsWith('/learning-expert.html')))u.pathname=u.pathname.replace(/learning(?:-expert)?\.html$/,'learning-expert.html');u.searchParams.set('edition',edition);return u.origin===location.origin?`${u.pathname}${u.search}${u.hash}`:u.toString()}catch{return''}}
function decision(m){const st=String(m.status||'').toLowerCase();if(st==='draft'||st==='coming_soon'||!m.launch_path)return{state:'coming',label:'Coming soon'};return{state:'open',label:'Open module'}}
function theme(m){const t=[m.title,m.category,m.slug].filter(Boolean).join(' ').toLowerCase();if(/ecg|rhythm|arrhythm/.test(t))return['module-ecg','Electrocardiography'];if(/echo|imaging|ct|mri|cmr/.test(t))return['module-imaging','Imaging'];if(/pci|tavi|transcatheter aortic|mitral|tricuspid|intervention|cto|left main|coronary intervention/.test(t))return['module-intervention','Interventional Cardiology'];return['module-general','General Cardiology']}
const answersOf=a=>Array.isArray(a?.answers)?a.answers:[];
const attemptDate=a=>new Date(a?.completed_at||a?.updated_at||a?.started_at||0);
function moduleAttempts(id){return attempts.filter(a=>String(a?.module_id)===String(id)).sort((a,b)=>attemptDate(b)-attemptDate(a))}
function answeredOf(a){const ans=answersOf(a);if(ans.length)return ans.length;const meta=a?.acl_metadata||{};const candidates=[meta.answeredCount,meta.answered_count,a?.answered_count,a?.current_index!=null?Number(a.current_index)+1:null,a?.question_count];for(const v of candidates){const n=Number(v);if(Number.isFinite(n)&&n>=0)return n}return 0}
function correctOf(a){const ans=answersOf(a);if(ans.length)return ans.filter(x=>x?.correct===true).length;const meta=a?.acl_metadata||{};for(const v of [a?.correct_count,meta.correctCount,meta.correct_count]){const n=Number(v);if(Number.isFinite(n)&&n>=0)return n}return 0}
function successPct(a){const n=answeredOf(a);return n?Math.round(correctOf(a)/n*100):null}
function lifelineCount(a){const l=a?.lifelines||a?.lifelines_state||{};return ['expert','filter','guideline','vault'].filter(k=>Boolean(l?.[k])).length}
function confidenceStats(rows){const o={total:0,calibrated:0};rows.flatMap(answersOf).forEach(x=>{if(!['high','low'].includes(x?.confidence))return;o.total++;if((x.correct&&x.confidence==='high')||(!x.correct&&x.confidence==='low'))o.calibrated++});return o}
function uniqueCoveredQuestions(rows,bank){const ids=new Set();let fallback=0;rows.forEach(a=>{const ans=answersOf(a);if(ans.length){let identified=0;ans.forEach(x=>{const id=x?.question_id??x?.questionId??x?.id??x?.question?.id;if(id!=null&&id!==''){ids.add(String(id));identified++}});if(!identified)fallback=Math.max(fallback,ans.length)}else fallback=Math.max(fallback,answeredOf(a))});const n=ids.size||fallback;return bank?Math.min(bank,n):n}
function rawMasteryPerformance(rows){const completed=rows.filter(a=>a?.status==='completed').sort((a,b)=>attemptDate(a)-attemptDate(b));if(!completed.length)return null;let sum=0,weight=0;completed.slice(-3).forEach((a,i)=>{const pct=successPct(a);if(pct===null)return;const w=i+1,cf=confidenceStats([a]),cal=cf.total?(.85+.15*(cf.calibrated/cf.total)):1,ind=Math.max(.72,1-lifelineCount(a)*.07);sum+=pct*w*cal*ind;weight+=w});if(!weight)return null;return Math.max(0,Math.min(100,sum/weight+Math.min(6,Math.max(0,completed.length-1)*1.5)))}
function masteryFor(rows,bank,covered){const raw=rawMasteryPerformance(rows);if(raw===null||!bank||!covered)return null;const coverage=Math.min(1,covered/bank);const evidence=Math.min(1,Math.sqrt(coverage/.60));return Math.max(0,Math.min(100,Math.round(raw*evidence)))}
function xpFor(rows){let xp=0;rows.filter(a=>a?.status==='completed').forEach(a=>{const ans=answersOf(a);if(ans.length){xp+=25-lifelineCount(a)*3;ans.forEach(x=>{if(x?.correct)xp+=10;if(x?.correct&&x?.confidence==='high')xp+=3;if(!x?.correct&&x?.confidence==='high')xp-=2})}else{const saved=Number(a?.score);if(Number.isFinite(saved)&&saved>0)xp+=saved}});return Math.max(0,Math.round(xp))}
function intelligence(m){const rows=moduleAttempts(m.id),latest=rows[0]||null,completed=rows.filter(a=>a?.status==='completed'),current=rows.find(a=>a?.status==='in_progress')||latest,bank=Math.max(0,Number(m.question_count)||0),covered=uniqueCoveredQuestions(rows,bank),progress=bank?Math.min(100,Math.round(covered/bank*100)):0,lastCompleted=completed[0]||null,success=lastCompleted?successPct(lastCompleted):null,mastery=masteryFor(rows,bank,covered),xp=xpFor(rows),coverage=bank?covered/bank:0;let state='Not started',stateClass='';if(decision(m).state!=='open'){state='Coming soon';stateClass='coming'}else if(coverage>=.60&&mastery!==null&&mastery>=80&&(success??0)>=80){state='Mastered';stateClass='mastered'}else if(covered>0&&coverage<.10){state='Early progress';stateClass='in-progress'}else if(covered>0&&coverage<.40){state='Building';stateClass='in-progress'}else if(covered>0&&coverage<.60){state='Developing';stateClass='in-progress'}else if(current?.status==='in_progress'||covered>0){state='In progress';stateClass='in-progress'}else if(completed.length){state='Completed';stateClass='completed'}return{rows,current,completed,bank,answered:covered,progress,success,mastery,xp,state,stateClass,coverage}}
function card(m){const d=decision(m),info=intelligence(m),href=d.state==='open'?launch(m):'',t=theme(m),action=['Early progress','Building','Developing','In progress'].includes(info.state)?'Continue module':info.state==='Mastered'||info.state==='Completed'?'Review / retry':d.label,guideline=isEscGuideline(m),success=info.success===null?'—':`${info.success}%`,mastery=info.mastery===null?'—':`${info.mastery}%`;return `<article class="module-card ${t[0]} ${d.state}${guideline?' is-esc-guideline':''}" data-module-id="${esc(m.id)}"><div class="module-cover"><span class="module-category">${esc(t[1])}</span></div><div class="module-card-body">${guideline?escBadge():''}<div class="module-card-heading"><h2>${esc(m.title||'ACL module')}</h2></div><div class="module-intel-status"><span class="state ${info.stateClass}">${esc(info.state)}</span></div><div class="module-intel-progress"><strong>${info.answered} / ${info.bank}</strong><div class="module-intel-track"><span style="width:${info.progress}%"></span></div><span>${info.progress}%</span></div><div class="module-intel-metrics"><div class="module-intel-metric"><span>Success</span><strong>${success}</strong></div><div class="module-intel-metric mastery"><span>Mastery</span><strong>${mastery}</strong></div><div class="module-intel-metric xp"><span>ACL XP</span><strong>${info.xp.toLocaleString()}</strong></div></div><div class="module-card-actions"><a class="module-action ${href?'':'disabled'}" href="${href?esc(href):'#'}" aria-label="${esc(action)}" title="${esc(action)}" ${href?'':'aria-disabled="true" tabindex="-1"'}>${esc(action)}</a></div></div></article>`}
function renderContinue(source=modules){const host=$('aclContinueLearning');if(!host)return;const preferred=source.map(m=>({m,info:intelligence(m)})).filter(x=>x.info.current?.status==='in_progress').slice(0,3);const rows=preferred.length?preferred:source.filter(m=>decision(m).state==='open').slice(0,3).map(m=>({m,info:intelligence(m)}));host.innerHTML=rows.length?rows.map(({m,info})=>{const href=launch(m),guideline=isEscGuideline(m),t=theme(m),intervention=t[0]==='module-intervention',ecg=t[0]==='module-ecg';const icon=guideline?'<img src="assets/images/esc-guideline-mark.svg" alt="ESC">':intervention?'<img src="assets/images/coronary-anatomy-module.svg" alt="Intervention">':ecg?'<img src="assets/images/ecg-module-logo.svg" alt="ECG">':'♡';const iconClass=guideline?' esc-guideline-icon':(intervention||ecg)?' module-art-icon':'';return `<article class="acl-continue-card"><div class="acl-continue-card-top"><div class="acl-continue-icon${iconClass}">${icon}</div><div class="acl-continue-copy"><h3>${esc(m.title)}</h3><small>${esc(info.state)} · ${info.answered}/${info.bank} questions</small></div><strong class="acl-continue-percent">${info.progress}%</strong></div><div class="acl-continue-progress"><span style="width:${info.progress}%"></span></div><a href="${esc(href)}" aria-label="Continue ${esc(m.title)}">›</a></article>`}).join(''):'<div class="card muted">No open modules yet.</div>'}
function filterModules(){const term=String(search?.value||'').trim().toLowerCase(),av=availability?.value||'all',pf=progressFilter?.value||'all';const rows=modules.filter(m=>{const d=decision(m),info=intelligence(m),text=[m.title,m.short_description,m.description,m.category,m.slug].filter(Boolean).join(' ').toLowerCase(),mt=!term||text.includes(term),ma=av==='all'||(av==='open'?d.state==='open':av==='locked'?d.state!=='open':true),mp=pf==='all'||(pf==='not-started'?info.state==='Not started':pf==='started'?['Early progress','Building','Developing','In progress'].includes(info.state):pf==='completed'?['Completed','Mastered'].includes(info.state):true);return mt&&ma&&mp});if(grid)grid.innerHTML=rows.length?rows.map(card).join(''):'<div class="module-filter-empty"><strong>No matching modules found</strong><p>Try changing the search or filters.</p></div>';if(searchSummary)searchSummary.textContent=`${rows.length} of ${modules.length} modules shown`;if(summary)summary.textContent=`${modules.length} modules`;renderContinue(rows)}
function timeout(promise,ms,label){return Promise.race([promise,new Promise((_,rej)=>setTimeout(()=>rej(new Error(`${label} timed out`)),ms))])}
async function loadCore(){show('Loading your ACL catalogue…');try{const core=await timeout(supabaseClient.from('modules').select('*').eq('edition',edition).order('display_order',{ascending:true}).order('title',{ascending:true}),8000,'Module catalogue');if(core.error)throw core.error;modules=Array.isArray(core.data)?core.data:[];if(grid)grid.innerHTML=modules.length?modules.map(card).join(''):'<div class="empty-state">No modules are currently available in this edition.</div>';if(summary)summary.textContent=`${modules.length} modules`;if(searchSummary)searchSummary.textContent=`${modules.length} modules available`;renderContinue(modules);show('');enhanceLater()}catch(e){console.error('ACL MODULE CORE LOAD ERROR',e);if(grid)grid.innerHTML=`<div class="empty-state"><strong>Could not load modules.</strong><p>${esc(e.message||'Please try again.')}</p></div>`;if(summary)summary.textContent='Catalogue unavailable';if(searchSummary)searchSummary.textContent='Unable to load modules';show(e.message||'Could not load modules.','error')}}
async function enhanceLater(){try{const sessionResult=await timeout(supabaseClient.auth.getSession(),5000,'Session'),user=sessionResult?.data?.session?.user;if(!user)return;const attemptResult=await timeout(supabaseClient.from('quiz_attempts').select('*').eq('user_id',user.id).order('updated_at',{ascending:false}),7000,'Progress');if(!attemptResult.error&&Array.isArray(attemptResult.data))attempts=attemptResult.data;filterModules();try{const dash=await timeout(supabaseClient.rpc('acl_get_my_learning_dashboard_v2',{p_edition:edition}),6000,'Learning dashboard');if(!dash.error&&dash.data){const d=dash.data;if($('aclStatInProgress'))$('aclStatInProgress').textContent=Number(d.open_attempts||d.modules_in_progress||0);if($('aclStatCompleted'))$('aclStatCompleted').textContent=Number(d.completed_attempts||0);if($('aclStatOverall'))$('aclStatOverall').textContent=`${Number(d.mastery_percent||0)}%`}}catch(e){console.warn('ACL dashboard enhancement skipped',e)}}catch(e){console.warn('ACL optional enhancement skipped',e)}}
search?.addEventListener('input',filterModules);availability?.addEventListener('change',filterModules);progressFilter?.addEventListener('change',filterModules);clear?.addEventListener('click',()=>{if(search)search.value='';if(availability)availability.value='all';if(progressFilter)progressFilter.value='all';filterModules()});$('moduleFilterToggle')?.addEventListener('click',()=>{const box=$('moduleCompactFilters');if(!box)return;box.hidden=!box.hidden;$('moduleFilterToggle').setAttribute('aria-expanded',String(!box.hidden))});loadCore();